function qv(k){return quizV2Words[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||quizV2Words[k]?.[0]||k}
const qe=ShamsQuizEngine;let quizV2Bank=null,quizSyncBusy=false,quizSyncError='',quizStartBusy=false,quizCatalogLoaded=false,quizReportRows=null,quizAudio=null;
function quizOwner(){return cloudState.session?.user?.id||'guest'}
function quizProfileKey(owner=quizOwner()){return 'shams-quiz-v2:'+owner}
function quizProfile(owner=quizOwner()){const p=read(quizProfileKey(owner),{});return {version:2,history:p.history||{},outbox:p.outbox||{},reports:p.reports||{},lastOrder:p.lastOrder||[],sound:p.sound!==false,migrated:!!p.migrated,syncedAt:p.syncedAt||0,views:p.views||{},session:p.session||null,adaptive:p.adaptive!==false,importedRounds:p.importedRounds||[],importedDaily:p.importedDaily||[]}}
function writeQuizProfile(p,owner=quizOwner()){if(!safeWrite(quizProfileKey(owner),p)){toast(qv('storage'));return false}return true}
function quizRawBank(){return quizV2Bank||SHAMS_QUIZ}
function quizEligible(){return quizRawBank().filter(q=>qe.usable(q,lang()))}
function quizFind(id){return quizRawBank().find(q=>q.id===id)||SHAMS_QUIZ.find(q=>q.id===id)}
function quizRecord(q,entry,answer){
 const owner=quizOwner(),p=quizProfile(owner),now=Date.now(),eventId=entry.eventId||('legacy-'+q.id+'-'+now);
 const id=eventId+(answer?':answer':':view');if(p.views[id]||p.outbox[id]||(!answer&&entry.shownAt))return true;
 p.history=qe.mark(p.history,q,{shownAt:entry.shownAt||now,answeredAt:answer?now:0,selectedId:answer?.selectedId});
 p.outbox[id]={event_id:id,question_id:q.id,shown_at:entry.shownAt||now,answered_at:answer?now:0,selected_id:answer?.selectedId||null};
 p.views[id]=now;if(Object.keys(p.views).length>2000){const oldest=Object.keys(p.views).sort((a,b)=>p.views[a]-p.views[b]);for(const k of oldest.slice(0,-2000))delete p.views[k]}
 if(!writeQuizProfile(p,owner))return false;entry.shownAt=entry.shownAt||now;
 if(owner!=='guest')setTimeout(syncQuizHistory,0);return true;
}
async function syncQuizHistory(){
 const owner=quizOwner();if(owner==='guest'||navigator.onLine===false||quizSyncBusy)return false;quizSyncBusy=true;
 try{
  // Owner is checked by the RPC as well as by the response guard: auth switches cannot mix histories.
  let p=quizProfile(owner),events=Object.values(p.outbox).slice(0,100),reports=Object.values(p.reports).slice(0,20);
  const result=await cloudRequest('/rest/v1/rpc/shams_quiz_sync',{p_owner:owner,p_events:events,p_reports:reports});if(quizOwner()!==owner)return false;
  p=quizProfile(owner);p.history=qe.merge(p.history,result.history||{});p.syncedAt=Date.now();for(const id of result.accepted||[])delete p.outbox[id];for(const id of result.reported||[])delete p.reports[id];
  if(!writeQuizProfile(p,owner))return false;quizSyncError='';if(Object.keys(p.outbox).length||Object.keys(p.reports).length)setTimeout(syncQuizHistory,0);return true;
 }catch(e){quizSyncError=e.message;return false}finally{quizSyncBusy=false}
}
async function mergeGuestQuizHistory(){if(quizOwner()==='guest')return;const p=quizProfile(),g=quizProfile('guest');p.history=qe.merge(p.history,g.history);p.outbox={...g.outbox,...p.outbox};p.importedRounds=[...new Set([...p.importedRounds,...quizStore().rounds.filter(r=>!r.owner||r.owner==='guest').map(r=>r.id)])];p.importedDaily=[...new Set([...p.importedDaily,...Object.keys(quizStore().daily).filter(k=>k.startsWith('guest|')||k.split('|').length<3)])];for(const [id,h]of Object.entries(g.history)){const q=quizFind(id);if(q)p.outbox['import:'+id+':'+h.shownAt]={event_id:'import:'+id+':'+h.shownAt,question_id:id,shown_at:h.shownAt,answered_at:h.answeredAt||0,selected_id:h.selectedId||null}};if(writeQuizProfile(p)){await syncQuizHistory();render()}}
async function quizBankCache(value){
 if(typeof indexedDB==='undefined')return null;
 return new Promise(resolve=>{const timer=setTimeout(()=>resolve(null),2000),done=v=>{clearTimeout(timer);resolve(v)},req=indexedDB.open('shams-quiz-catalog',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('bank'))req.result.createObjectStore('bank')};req.onerror=()=>done(null);req.onblocked=()=>done(null);req.onsuccess=()=>{const db=req.result;try{const tx=db.transaction('bank',value?'readwrite':'readonly'),store=tx.objectStore('bank'),op=value?store.put(value,'approved'):store.get('approved');let result=null;op.onsuccess=()=>{result=op.result};tx.oncomplete=()=>{db.close();done(result)};tx.onerror=()=>{db.close();done(null)}}catch{db.close();done(null)}}});
}
async function loadQuizCatalog(){
 if(quizCatalogLoaded)return;quizCatalogLoaded=true;
 const cache=await quizBankCache().catch(()=>null);if(Array.isArray(cache)&&cache.length<=5000&&!qe.audit(cache).errors.length)quizV2Bank=cache;if(navigator.onLine===false)return;
 try{const next=[];for(let offset=0;offset<5000;offset+=250){const batch=await cloudRequest('/rest/v1/rpc/shams_quiz_catalog',{p_offset:offset},'POST',false);if(!Array.isArray(batch))throw Error('Invalid catalog');next.push(...batch);if(batch.length<250)break}if(next.length<=5000&&!qe.audit(next).errors.length){quizV2Bank=next;await quizBankCache(next)}}catch{ /* Keep the last complete approved catalog, including the bundled offline bank. */ }
}
function quizSound(correct){const p=quizProfile();if(!p.sound)return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;quizAudio=quizAudio||new A();quizAudio.resume().catch(()=>{});const o=quizAudio.createOscillator(),g=quizAudio.createGain(),t=quizAudio.currentTime;o.type=correct?'sine':'triangle';o.frequency.setValueAtTime(correct?660:230,t);o.frequency.exponentialRampToValueAtTime(correct?880:150,t+.12);g.gain.setValueAtTime(.05,t);g.gain.exponentialRampToValueAtTime(.001,t+.2);o.connect(g).connect(quizAudio.destination);o.onended=()=>{o.disconnect();g.disconnect()};o.start(t);o.stop(t+.21)}catch{}}
function quizSetAdaptive(on){const p=quizProfile();p.adaptive=on;writeQuizProfile(p);render()}
function quizToggleSound(on){const p=quizProfile();p.sound=on;writeQuizProfile(p)}
function quizOwnedRounds(){const owner=quizOwner(),p=quizProfile(owner);return quizStore().rounds.filter(r=>(r.owner||'guest')===owner||p.importedRounds.includes(r.id))}
function quizOwnedDaily(){const owner=quizOwner(),p=quizProfile(owner);return Object.entries(quizStore().daily).filter(([k])=>k.startsWith(owner+'|')||(owner==='guest'&&k.split('|').length<3)||p.importedDaily.includes(k)).map(([,v])=>v)}
function quizV2Totals(){const rounds=quizOwnedRounds(),answers=rounds.flatMap(r=>r.answers).filter(a=>a&&typeof a.id==='string').concat(quizOwnedDaily().filter(a=>a?.id));return {correct:answers.filter(a=>a.correct).length,total:answers.length,rounds:rounds.length,perfect:rounds.some(r=>r.total===10&&r.correct===10),categories:new Set(rounds.flatMap(r=>r.questions.filter(Boolean).map(e=>qe.topic(e.snapshot||quizFind(e.id)||{}))).filter(Boolean)).size}}
function quizV2Mistakes(){const latest={};for(const a of [...quizOwnedRounds().flatMap(r=>r.answers.map(a=>({...a,at:r.completedAt||r.startedAt||0}))),...quizOwnedDaily()].sort((a,b)=>(a.at||0)-(b.at||0)))if(a.id)latest[a.id]=a.correct;return Object.keys(latest).filter(id=>latest[id]===false)}
async function submitRankedScoreV2(){
 const owner=quizOwner(),initial=quizStore(),r=quizOwnedRounds().find(r=>r.id===initial.session?.id)||quizOwnedRounds().at(-1);
 if(owner==='guest'||!r?.rankedId||r.rankConfirmed||scoreBusy)return;scoreBusy=true;scoreError=false;
 try{const result=await cloudRequest('/rest/v1/rpc/shams_quiz_finish',{p_round:r.rankedId,p_answers:r.answers.map(a=>a.selected)});const current=quizStore(),saved=current.rounds.find(x=>x.id===r.id);
  if(saved){saved.rankConfirmed=true;saved.awarded=result.awarded}if(current.session?.id===r.id){current.session.rankConfirmed=true;current.session.awarded=result.awarded}safeWrite('shams-quiz',current);leaderData=null;if(quizOwner()===owner)toast('+'+result.awarded+' '+c17('points'));
 }catch{if(quizOwner()===owner){scoreError=true;toast(c17('scoreError'))}}finally{scoreBusy=false;if(quizOwner()===owner&&route==='quiz'&&location.hash.endsWith('/result'))render()}
}
function quizV2History(){const rows=quizOwnedRounds();return head(ml('results'),'')+(rows.length?rows.slice().reverse().map(r=>`<article class="card"><b>${esc(r.date)}</b><p>${r.correct} / ${r.total} · ${ml('correct')}</p><p>${r.level===4?ml('expert'):qv(['easy','medium','hard'][r.level-1])}</p></article>`).join(''):`<p class="card">${ml('empty')}</p>`)}
function quizOwnStreak(){const days=new Set(quizOwnedRounds().map(r=>r.date));for(const d of quizOwnedDaily())if(d?.date)days.add(d.date);const date=placeToday();if(!days.has(key(date)))date.setDate(date.getDate()-1);let streak=0;while(days.has(key(date))){streak++;date.setDate(date.getDate()-1)}return streak}
function quizV2Achievements(){const t=quizTotals(),legacy=new Set(quizOwnedRounds().filter(r=>!r.owner).flatMap(r=>r.questions.filter(Boolean).map(e=>quizFind(e.id)?.category)).filter(Boolean));const items=[['ach10',t.correct>=10],['ach50',t.correct>=50],['ach100',t.correct>=100],['perfect',t.perfect],['streak',quizOwnStreak()>=7],['allCategories',t.categories===8||legacy.size===8]];return head(ml('achievements'),'')+`<div class="achievement-list">${items.map(([k,on])=>`<article class="card ${on?'earned':''}"><strong>${ml(k)}</strong><b>${on?'✓':'○'}</b></article>`).join('')}</div>`}
function quizV2Result(){const s=quizStore(),r=quizOwnedRounds().find(r=>r.id===s.session?.id)||quizOwnedRounds().at(-1);if(!r)return quizV2Home();return head(ml('results'),'')+`<section class="card result-card"><strong dir="ltr">${r.correct*10} / ${r.total*10}</strong><div class="learning-metrics"><span><b>${r.correct}</b>${ml('correct')}</span><span><b>${r.total-r.correct}</b>${ml('wrong')}</span><span><b>${Math.round(r.correct/r.total*100)}%</b>${ml('accuracy')}</span></div><button class="goldbtn" onclick="startQuiz('${qe.categories.includes(r.category)?r.category:r.category==='names'?'basics':r.category==='culture'?'general':'all'}',${Math.min(3,r.level)})">${ml('again')}</button><button class="secondarybtn" onclick="go('leaderboard')">${c17('leaderboard')}</button><p class="notice">${r.rankedId?(r.rankConfirmed?'+'+r.awarded+' '+c17('points'):scoreBusy?c17('pendingScore'):c17('scoreError')):c17('unranked')}</p>${r.rankedId&&!r.rankConfirmed?`<button class="secondarybtn" onclick="submitRankedScore()">${c17('retry')}</button>`:''}</section><div class="quiz-review">${r.answers.filter(Boolean).map(a=>{const archived=r.questions.find(e=>e.id===a.id),q=(s.session?.id===r.id?s.session.questions.find(e=>e.id===a.id)?.snapshot:null)||archived?.snapshot||quizFind(a.id);return q&&qe.usable(q,lang())?`<details><summary>${a.correct?'✓':'×'} ${esc(q.question[lang()])}</summary>${archived?.correctOptionId&&archived.correctOptionId!==qe.correctId(q)?`<p class="notice">${qv('updatedQuestion')}</p>`:''}<p>${esc(q.options[q.correct][lang()])}</p><p>${esc(q.explanation[lang()])}</p>${quizSource(q)}<button class="textbtn" onclick="reportQuizQuestion('${q.id}')">${qv('report')}</button></details>`:''}).join('')}</div>`}
function quizV2Home(){
 setTimeout(loadQuizCatalog,0);setTimeout(syncQuizHistory,0);const s=quizStore(),stats=quizTotals(),pool=quizEligible();if(quizProfile().adaptive)quizLevel=qe.recommend(quizOwnedRounds());
 return head(ux('quiz'),'')+`<div data-localized="true" class="quiz-v2"><p class="notice">${qv('available')}: ${pool.length} · ${quizOwner()==='guest'?qv('guest'):quizSyncError||!quizProfile().syncedAt?qv('offline'):qv('sync')}</p><div class="learning-metrics"><span><b>${stats.correct}</b>${ml('correct')}</span><span><b>${stats.total?Math.round(stats.correct/stats.total*100):0}%</b>${ml('accuracy')}</span><span><b>${stats.rounds}</b>${ml('round')}</span></div>${s.session&&!s.session.finished&&(!s.session.owner||s.session.owner===quizOwner())?`<button class="goldbtn wide" onclick="go('quiz/play')">${ml('resume')}</button>`:''}<section class="card game-setup"><label>${ml('level')}<select onchange="quizLevel=Number(this.value);quizSetAdaptive(false)">${['easy','medium','hard'].map((l,i)=>`<option value="${i+1}" ${quizLevel===i+1?'selected':''}>${qv(l)}</option>`).join('')}</select></label><label>${ml('category')}<select onchange="quizCategory=this.value;render()"><option value="all">${ml('all')}</option>${qe.categories.map(c=>`<option value="${c}" ${quizCategory===c?'selected':''}>${quizV2Words[c]?qv(c):ml(c)} (${pool.filter(q=>qe.topic(q)===c).length})</option>`).join('')}</select></label><label class="cloud-consent"><input type="checkbox" ${quizProfile().adaptive?'checked':''} onchange="quizSetAdaptive(this.checked)">${qv('adaptive')}</label><label class="cloud-consent"><input type="checkbox" ${quizProfile().sound?'checked':''} onchange="quizToggleSound(this.checked)">${qv('sound')}</label><button id="quizStartButton" class="goldbtn wide" onclick="startQuiz()" ${quizStartBusy?'disabled':''}>${ml('start')}</button></section><div class="module-actions">${[['results','results'],['achievements','achievements'],['mistakes','mistakes'],['daily','dailyQuestion']].map(([r,k])=>`<button class="secondarybtn" onclick="go('quiz/${r}')">${ml(k)}</button>`).join('')}<button class="secondarybtn" onclick="go('leaderboard')">${c17('leaderboard')}</button></div>${quizOwner()!=='guest'&&Object.keys(quizProfile('guest').history).length?`<button class="textbtn" onclick="mergeGuestQuizHistory()">${qv('importGuest')}</button>`:''}${quizOwner()!=='guest'&&Object.keys(quizProfile('guest').reports).length?`<button class="textbtn" onclick="sendGuestQuizReports()">${qv('sendGuestReports')}</button>`:''}</div>`;
}
async function startQuizV2(category=quizCategory,level=quizLevel,mode='normal'){
 if(quizStartBusy)return;quizStartBusy=true;const button=document.querySelector('#quizStartButton');if(button){button.disabled=true;button.textContent=v16('preparing')}const owner=quizOwner();
 try{
  void loadQuizCatalog();if(owner!=='guest')await syncQuizHistory();if(quizOwner()!==owner)return;
  let p=quizProfile(owner);const s=quizStore();level=p.adaptive?qe.recommend(s.rounds):Math.min(3,Math.max(1,Number(level)||1));
  let bank=quizEligible();if(mode==='mistakes'){const wrong=quizMistakes();bank=bank.filter(q=>wrong.includes(q.id));category='all'}
  let entries=qe.select(bank,{language:lang(),category,level,history:p.history,previous:p.lastOrder});if(!entries.length)return toast(qv('empty'));
  let rankedId=null;if(owner!=='guest'&&mode==='normal'&&!quizSyncError&&entries.length===10){try{const r=await cloudRequest('/rest/v1/rpc/shams_quiz_start_v2',{p_owner:owner,p_category:category,p_level:level,p_language:lang()});if(r?.id&&r.questions.length===10&&r.questions.every(id=>bank.some(q=>q.id===id))){rankedId=r.id;entries=r.questions.map(id=>{const q=quizFind(id),optionIds=qe.shuffled(qe.optionIds(q));return {id,optionIds,order:optionIds.map(i=>qe.optionIds(q).indexOf(i))}})}}catch{rankedId=null}}
  if(quizOwner()!==owner)return;const id=rankedId?'rank-'+rankedId:'round-'+Date.now()+'-'+Math.random().toString(36).slice(2);
  entries=entries.map(e=>({...e,eventId:id+':'+e.id,snapshot:quizFind(e.id)}));s.session={id,owner,rankedId,category,level,mode,index:0,questions:entries,answers:[],startedAt:Date.now()};p=quizProfile(owner);p.lastOrder=entries.map(e=>e.id);p.session=s.session;
  if(!writeQuizProfile(p,owner)||!safeWrite('shams-quiz',s))return toast(qv('storage'));if(entries.length<10)toast(qv('short'));go('quiz/play');render();
 }catch(e){toast(e.message||qv('offline'))}finally{quizStartBusy=false;if(button){button.disabled=false;button.textContent=ml('start')}}
}
function quizV2Play(){
 const s=quizStore(),session=s.session;if(!session||session.finished)return quizV2Home();if(session.owner&&session.owner!==quizOwner())return quizV2Home();const entry=session.questions[session.index],q=entry.snapshot||quizFind(entry.id);if(!q||!qe.usable(q,lang()))return `<p class="card">${qv('empty')}</p><button class="goldbtn" onclick="go('quiz')">${ml('home')}</button>`;
 if(!quizRecord(q,entry))return `<p role="alert">${qv('storage')}</p>`;safeWrite('shams-quiz',s);const a=session.answers[session.index],ids=entry.optionIds||entry.order.map(i=>qe.optionIds(q)[i]);
 return head(ux('quiz'),'')+`<div data-localized="true" class="quiz-v2" dir="${lang()==='ar'?'rtl':'ltr'}"><div class="question-counter"><span>${session.index+1} / ${session.questions.length}</span></div><article class="question-card quiz-transition" data-question="${esc(q.id)}"><small>${quizV2Words[qe.topic(q)]?qv(qe.topic(q)):ml(qe.topic(q))} · ${qv(['easy','medium','hard'][qe.tier(q)-1])}</small><h2>${esc(q.question[lang()])}</h2><div class="answer-options">${ids.map((id,i)=>`<button data-option-id="${esc(id)}" class="${a?(id===qe.correctId(q)?'correct':id===(a.selectedId||qe.optionIds(q)[a.selected])?'incorrect':''):''}" ${a?'disabled':''} onclick="answerQuizV2(this.dataset.optionId)"><b>${lang()==='ar'?['أ','ب','ج','د'][i]:'ABCD'[i]}</b><span>${esc(q.options[qe.optionIds(q).indexOf(id)][lang()])}</span></button>`).join('')}</div>${a?`<section class="answer-explanation"><strong>${ml(a.correct?'correct':'wrong')}</strong><p>${esc(q.explanation[lang()])}</p>${quizSource(q)}</section><button class="goldbtn wide" onclick="advanceQuiz()">${ml(session.index===session.questions.length-1?'finish':'next')}</button>`:''}<button class="textbtn" onclick="reportQuizQuestion('${esc(q.id)}')">${qv('report')}</button></article></div>`;
}
function answerQuizV2(id){const s=quizStore(),t=s.session;if(!t||t.answers[t.index]||(t.owner&&t.owner!==quizOwner()))return;const entry=t.questions[t.index],q=entry.snapshot||quizFind(entry.id);if(!q||!(entry.optionIds||entry.order.map(i=>qe.optionIds(q)[i])).includes(id))return;const answer={id:q.id,selectedId:id,selected:qe.optionIds(q).indexOf(id),correct:qe.answer(q,id)};if(!quizRecord(q,entry,answer))return;t.answers[t.index]=answer;const p=quizProfile();p.session=t;if(writeQuizProfile(p)&&safeWrite('shams-quiz',s)){quizSound(answer.correct);render()}}
function advanceQuizV2(){
 const s=quizStore(),t=s.session;if(!t||t.finished||!t.answers[t.index]||(t.owner&&t.owner!==quizOwner()))return;
 if(t.index<t.questions.length-1)t.index++;
 else{
  if(!s.rounds.some(r=>r.id===t.id)){
   // Archive compact references, not ten copies of the five-language bank on every round.
   const questions=t.questions.map(({snapshot,...entry})=>({...entry,correctOptionId:snapshot?qe.correctId(snapshot):qe.correctId(quizFind(entry.id))}));
   s.rounds.push({...t,questions,owner:t.owner||quizOwner(),date:key(placeToday()),completedAt:Date.now(),timezone:place().timezone,correct:t.answers.filter(a=>a.correct).length,total:t.questions.length});
   if(t.mode==='normal')s.unlocked=Math.max(s.unlocked,Math.min(4,t.level+1));
  }t.finished=true;
 }
 const p=quizProfile();p.session=t;if(!writeQuizProfile(p)||!safeWrite('shams-quiz',s))return;
 if(t.finished){go('quiz/result');render();if(t.rankedId)submitRankedScore()}else render();
}
async function reportQuizQuestion(id){const note=window.prompt(qv('reason'));if(!note?.trim())return;const p=quizProfile(),key='qr-'+Date.now()+'-'+Math.random().toString(36).slice(2);p.reports[key]={id:key,question_id:id,language:lang(),note:note.trim().slice(0,1000)};if(!writeQuizProfile(p))return;if(quizOwner()==='guest')return toast(qv('guestReport'));const ok=await syncQuizHistory();toast(qv(ok?'reported':'queued'))}
async function sendGuestQuizReports(){const owner=quizOwner();if(owner==='guest')return;const guest=quizProfile('guest'),ids=Object.keys(guest.reports),p=quizProfile(owner);p.reports={...guest.reports,...p.reports};if(!writeQuizProfile(p,owner))return;const ok=await syncQuizHistory();if(quizOwner()!==owner)return;const current=quizProfile(owner),g=quizProfile('guest');for(const id of ids)if(!current.reports[id])delete g.reports[id];writeQuizProfile(g,'guest');render();toast(qv(ok?'reported':'queued'))}
async function quizImportJSON(form){try{const rows=JSON.parse(form.elements.questions.value);if(!Array.isArray(rows)||!rows.length||rows.length>5000)throw Error('1–5000 questions required');for(const q of rows){const e=qe.validate(q,{newContent:true});if(e.length)throw Error(q.id+': '+e.join(', '))}const audit=qe.audit(rows);if(audit.errors.length||audit.duplicates.length||audit.candidates.length)throw Error('Duplicate/source-answer candidates require editorial comparison');await cloudRequest('/rest/v1/rpc/shams_quiz_import',{p_questions:rows});quizCatalogLoaded=false;await loadQuizCatalog();toast(cw('saved'))}catch(e){toast(e.message)}}
async function loadQuizReports(){try{quizReportRows=await cloudRequest('/rest/v1/rpc/shams_quiz_reports',{});if(route==='cloudadmin')render()}catch(e){quizReportRows=[];toast(e.message)}}
async function resolveQuizReport(id){try{await cloudRequest('/rest/v1/rpc/shams_quiz_report_resolve',{p_id:id});await loadQuizReports()}catch(e){toast(e.message)}}
function initializeQuizUpgrade(){
 approvedQuestions=quizEligible;quizText=value=>typeof value==='string'?value:value?.[lang()]||'';startQuiz=startQuizV2;quizHome=quizV2Home;quizPlay=quizV2Play;quizResult=quizV2Result;quizTotals=quizV2Totals;quizMistakes=quizV2Mistakes;quizHistory=quizV2History;quizAchievements=quizV2Achievements;submitRankedScore=submitRankedScoreV2;
 answerQuiz=function(index){const t=quizStore().session,q=quizFind(t?.questions[t.index]?.id);if(q)answerQuizV2(qe.optionIds(q)[index])};
 // Migrate known *shown* legacy questions only to the guest profile. Never delete old scores or claim another account's local history.
 const p=quizProfile('guest');if(!p.migrated){const old=quizStore();for(const r of old.rounds)for(const a of r.answers){const q=quizFind(a.id);if(q)p.history=qe.mark(p.history,q,{shownAt:r.completedAt||r.startedAt||1,answeredAt:r.completedAt||r.startedAt||1,selectedId:qe.optionIds(q)[a.selected]})}for(const d of Object.values(old.daily)){const q=quizFind(d.id);if(q)p.history=qe.mark(p.history,q,{shownAt:d.at||1,answeredAt:d.at||1,selectedId:qe.optionIds(q)[d.selected]})}p.migrated=true;writeQuizProfile(p,'guest')}
 const oldDailyKey=dailyQuizKey;dailyQuizKey=()=>quizOwner()+'|'+oldDailyKey();
 const previousDaily=dailyQuestion;dailyQuestion=function(){const k=dailyQuizKey(),a=quizStore().daily[k];return a?quizFind(a.id):previousDaily()};
 const dailyPage=dailyQuizPage;dailyQuizPage=function(){const q=dailyQuestion();if(q){quizRecord(q,{eventId:'daily:'+dailyQuizKey()+':'+q.id,shownAt:0});return dailyPage()+`<button class="textbtn" onclick="reportQuizQuestion('${q.id}')">${qv('report')}</button>`}return quizV2Home()};
 const dailyAnswer=answerDailyQuiz;answerDailyQuiz=function(index){const q=dailyQuestion(),s=quizStore();if(!q||s.daily[dailyQuizKey()])return;dailyAnswer(index);const a=quizStore().daily[dailyQuizKey()];if(a){quizRecord(q,{eventId:'daily:'+dailyQuizKey()+':'+q.id},{...a,selectedId:qe.optionIds(q)[index]});quizSound(a.correct)}};
 const admin=cloudAdminPage;cloudAdminPage=function(){const html=admin();if(!cloudState.admin)return html;return html+`<details class="card"><summary>${qv('bank')}</summary><p>${qv('reviewNote')}</p><form class="cloud-form" onsubmit="event.preventDefault();quizImportJSON(this)"><label>JSON<textarea name="questions" required rows="8"></textarea></label><button class="goldbtn">${qv('importBank')}</button></form><button class="secondarybtn" onclick="loadQuizReports()">${c17('refresh')}</button>${(quizReportRows||[]).map(r=>`<article><b>${esc(r.question_id)} · ${esc(r.language)}</b><p>${esc(r.note)}</p><button class="textbtn" onclick="resolveQuizReport('${esc(r.id)}')">${c18('resolved')}</button></article>`).join('')}</details>`};
 const storeSession=cloudStoreSession;cloudStoreSession=function(session){const old=quizStore();if(old.session){const owner=old.session.owner||'guest',p=quizProfile(owner);p.session=old.session;writeQuizProfile(p,owner)}const before=quizOwner();storeSession(session);if(before!==quizOwner()){old.session=quizProfile().session;safeWrite('shams-quiz',old)}quizSyncError='';setTimeout(syncQuizHistory,0)};
 advanceQuiz=advanceQuizV2;
 window.addEventListener('online',()=>{quizCatalogLoaded=false;loadQuizCatalog();syncQuizHistory()});window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#quiz'))syncQuizHistory()});
}
